/* 
  Common Content-Type Examples 
*/

// 1. JSON Data (99% of API interactions)
Content-Type: application/json

// 2. File Uploads (Images, PDFs)
Content-Type: multipart/form-data; boundary=----WebKitFormBoundary7MA4

// 3. Standard HTML Form Submission (URL Encoded)
Content-Type: application/x-www-form-urlencoded

// 4. Returning a Web Page to the Browser
Content-Type: text/html; charset=UTF-8

// 5. Returning an Image
Content-Type: image/jpeg
